-- Test customers for Customer Milk Delivery (same as the API seeds on start when ENV=development). Safe to re-run.
-- Existing customer types with the same name (any case, e.g. School, Individual) are reused.
INSERT INTO customers (customer_type_id, full_names, phone, email_address, customer_no, status, credit_limit, rate, payment_terms_days, postal_town, created_at, updated_at) SELECT (SELECT id FROM customer_types WHERE LOWER(name) = LOWER('Company') AND deleted_at IS NULL ORDER BY id LIMIT 1), 'Kiambu Fresh Dairies Ltd', '254711000001', 'devcus001@customers.test', 'DEV-CUS-001', 'ACTIVE', 500000, 52, 30, 'Kiambu', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM customers WHERE customer_no = 'DEV-CUS-001');
UPDATE customers SET customer_type_id = (SELECT id FROM customer_types WHERE LOWER(name) = LOWER('Company') AND deleted_at IS NULL ORDER BY id LIMIT 1) WHERE customer_no = 'DEV-CUS-001';
