UPDATE customer_types ct SET ct.deleted_at = NOW() WHERE ct.deleted_at IS NULL AND ct.description LIKE '% (test data)' AND NOT EXISTS (SELECT 1 FROM customers c WHERE c.customer_type_id = ct.id AND c.deleted_at IS NULL);
UPDATE customers SET deleted_at = NULL, status = 'ACTIVE' WHERE customer_no LIKE 'DEV-CUS-%';
SELECT c.customer_no, c.full_names, ct.name AS customer_type FROM customers c LEFT JOIN customer_types ct ON ct.id = c.customer_type_id WHERE c.customer_no LIKE 'DEV-CUS-%';
